package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;import java.util.*;
/** Persistent portfolio for jobs/crafting/research/training/administration/social projects. No rewards are invented. */
public final class DowntimeProjectPortfolioEngine{
 private DowntimeProjectPortfolioEngine(){}
 public static JSONObject empty(){JSONObject o=new JSONObject();try{o.put("projects",new JSONObject()).put("version",1);}catch(Exception ignored){}return o;}
 public static JSONObject upsert(JSONObject state,JSONObject raw,int day){JSONObject s=copy(state);try{JSONObject p=copy(raw);String id=p.optString("id").trim();if(id.isEmpty())throw new IllegalArgumentException("project id required");String family=p.optString("family").trim();if(family.isEmpty())family=familyFor(p.optString("type"));if(family.isEmpty())throw new IllegalArgumentException("unknown downtime family");p.put("family",family).put("last_day",Math.max(1,day));if(p.optString("status").isEmpty())p.put("status","planned");JSONObject ps=s.optJSONObject("projects");if(ps==null){ps=new JSONObject();s.put("projects",ps);}ps.put(id,p);}catch(Exception e){throw new IllegalArgumentException(e.getMessage());}return s;}
 public static JSONObject advance(JSONObject state,String id,double units,int day){JSONObject s=copy(state);JSONObject p=s.optJSONObject("projects").optJSONObject(id);if(p==null)throw new IllegalArgumentException("unknown project");try{if("completed".equals(p.optString("status"))||"cancelled".equals(p.optString("status")))return s;double next=p.optInt("progress",0)+Math.max(0,units);p.put("progress",next).put("last_day",Math.max(1,day)).put("status","active");double required=p.optInt("required_progress",0);if(required>0&&next>=required)p.put("status","awaiting_authorized_resolution");}catch(Exception ignored){}return s;}
 public static JSONObject resolveAuthorized(JSONObject state,String id,String ruleId,JSONObject inputs,JSONObject mutation,int day){JSONObject s=copy(state);JSONObject ps=s.optJSONObject("projects");JSONObject p=ps==null?null:ps.optJSONObject(id);if(p==null)throw new IllegalArgumentException("unknown project");if(!"awaiting_authorized_resolution".equals(p.optString("status")))throw new IllegalArgumentException("project not awaiting resolution");JSONObject envelope=AuthorizedMechanicalMutationEngine.mutationEnvelope(ruleId,inputs,mutation);try{p.put("resolution_rule_id",ruleId==null?"":ruleId).put("resolution_inputs",inputs==null?new JSONObject():inputs).put("resolution_envelope",envelope).put("last_day",Math.max(1,day));if(envelope.optBoolean("executed")&&envelope.optBoolean("mutation_authorized"))p.put("status","authorized_resolution_ready");else p.put("status","awaiting_authorized_resolution");}catch(Exception ignored){}return s;}
 public static JSONObject setStatus(JSONObject state,String id,String status,int day){JSONObject s=copy(state);JSONObject ps=s.optJSONObject("projects"),p=ps==null?null:ps.optJSONObject(id);if(p==null)throw new IllegalArgumentException("unknown project");String next=status==null?"":status.trim().toLowerCase();String current=p.optString("status","planned");if("completed".equals(current)||"cancelled".equals(current))throw new IllegalArgumentException("terminal project cannot change status");if(!("planned".equals(next)||"active".equals(next)||"paused".equals(next)||"cancelled".equals(next)))throw new IllegalArgumentException("invalid project status");try{p.put("status",next).put("last_day",Math.max(1,day));if("paused".equals(next))p.put("paused_day",Math.max(1,day));if("cancelled".equals(next))p.put("cancelled_day",Math.max(1,day));}catch(Exception ignored){}return s;}
 public static JSONObject recordJobShift(JSONObject state,String id,double attendanceUnits,int day){JSONObject s=copy(state);JSONObject ps=s.optJSONObject("projects"),p=ps==null?null:ps.optJSONObject(id);if(p==null)throw new IllegalArgumentException("unknown project");if(!"job".equals(p.optString("family")))throw new IllegalArgumentException("project is not job family");if("paused".equals(p.optString("status"))||"cancelled".equals(p.optString("status"))||"completed".equals(p.optString("status")))throw new IllegalArgumentException("job is not active");double units=Math.max(0,attendanceUnits);try{p.put("attendance_units",p.optDouble("attendance_units",0)+units).put("shifts_worked",p.optInt("shifts_worked",0)+1).put("last_shift_day",Math.max(1,day));}catch(Exception ignored){}return advance(s,id,units,day);}
 public static JSONArray active(JSONObject state){JSONArray a=new JSONArray();JSONObject ps=state==null?null:state.optJSONObject("projects");if(ps==null)return a;Iterator<String> it=ps.keys();while(it.hasNext()){JSONObject p=ps.optJSONObject(it.next());if(p!=null&&!"completed".equals(p.optString("status"))&&!"cancelled".equals(p.optString("status")))a.put(copy(p));}return a;}
 public static JSONObject advanceDay(JSONObject state,int day){JSONObject s=copy(state);JSONObject ps=s.optJSONObject("projects");if(ps==null)return s;Iterator<String>it=ps.keys();while(it.hasNext()){String id=it.next();JSONObject p=ps.optJSONObject(id);if(p==null)continue;int deadline=p.optInt("deadline_day",0);String status=p.optString("status");try{p.put("current_day",Math.max(1,day));if(deadline>0&&day>deadline&&!"completed".equals(status)&&!"cancelled".equals(status))p.put("overdue",true).put("overdue_days",day-deadline);else if(deadline>0&&day<=deadline){p.put("overdue",false).put("overdue_days",0);}}catch(Exception ignored){}}return s;}

 private static String familyFor(String t){if(t==null)return "";if(t.equals("trabalho"))return "job";if(t.equals("artesanato"))return "craft";if(t.equals("comercio"))return "trade";if(t.equals("pesquisa"))return "research";if(t.equals("estudo"))return "training";if(t.equals("administracao"))return "administration";if(t.equals("vida_social"))return "social";return "";}
 private static JSONObject copy(JSONObject o){try{return o==null?empty():new JSONObject(o.toString());}catch(Exception e){return empty();}}
}
